// Generates `backend/pb_migrations/1784000000_created_*.js` for the base
// collections that historically had NO created_* migration in this repo (their
// schema lived only in the developer's admin UI / pb_data, so a fresh instance
// crashed on the very first updated_* migration).
//
// The generated files carry the FINAL schema from `web/scripts/pb-schema.json`
// (canonical snapshot, exported from a bootstrapped PocketBase 0.39 instance),
// with the collection ids REPLACED by the canonical ids that the existing
// updated_* migrations reference, and every relation field re-pointed at those
// canonical ids.
//
// Regenerate with:
//   node web/scripts/gen-created-migrations.mjs
//
// The generator is idempotent: files are rewritten in place. If a collection
// gets a NEW field in the future, re-export pb-schema.json, rerun this script,
// and (for existing deployments) also add an updated_* migration for the diff.

import { readFileSync, writeFileSync, existsSync, readdirSync, rmSync } from "node:fs"
import { join, dirname } from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..")
const SCHEMA = join(ROOT, "web", "scripts", "pb-schema.json")
const MIG_DIR = join(ROOT, "backend", "pb_migrations")

// Timestamps are dependency-ordered: PocketBase validates relation targets at
// save time, so a collection must exist before another may reference it.
// All are < 1784886276 (the oldest historical migration).
const TS = {
  departments: "1784000001",
  roles: "1784000002",
  plans: "1784000003",
  tasks: "1784000004",
  comments: "1784000005",
  proposals: "1784000006",
  kpi_scores: "1784000007",
  notifications: "1784000008",
  system_logs: "1784000009",
  users: "1784000010", // sync (users always exists)
}
// sync migrations that must run AFTER professional_groups exists (1786900000),
// because PB validates relation targets on save
const USERS_GROUP_IDS_FILE = "1787000000_sync_users_group_ids.js"
const PLANS_GROUP_ID_FILE = "1787000001_sync_plans_group_id.js"

// snapshot collection id -> canonical id used by the existing updated_* migrations
const ID_MAP = {
  pbc_departments: "pbc_3865025440",
  pbc_roles: "pbc_2105053228",
  pbc_plans: "pbc_4263585338",
  pbc_tasks: "pbc_2602490748",
  pbc_comments: "pbc_533777971",
  pbc_proposals: "pbc_3247561751",
  pbc_kpi_scores: "pbc_1748357255",
  pbc_notifications: "pbc_2301922722",
  pbc_system_logs: "pbc_296900318",
}

// collections in the snapshot that ALREADY have a created_* migration in the chain
const SKIP = new Set([
  "professional_groups", "employee_profiles", "leave_requests", "leave_balances",
  "attendance_logs", "attendance_configs", "qualifications", "salary_records",
  "work_experiences", "chat_messages", "announcements", "archived_plans",
  "presence_heartbeats", "presence_campaigns", "presence_check_logs",
  "archived_tasks", "archived_comments",
])

// The `users` auth collection is auto-created by PocketBase on fresh boot with
// only the default fields; the custom fields (department_id, role_id, ...) were
// added in the admin UI and never migrated. We sync them in created_users.

function loadSchema() {
  const raw = JSON.parse(readFileSync(SCHEMA, "utf8"))
  return Array.isArray(raw) ? raw : raw.collections
}

function canonicalId(snapshotId) {
  return ID_MAP[snapshotId] || snapshotId
}

function rewriteRelations(fields) {
  return fields.map((f) =>
    f.type === "relation" ? { ...f, collectionId: canonicalId(f.collectionId) } : f
  )
}

function json(x) {
  return JSON.stringify(x, null, 2)
}

// base collection migration — guarded by existence so existing deployments no-op
function createdMigration(name, collection) {
  const body = json({
    ...collection,
    id: canonicalId(collection.id),
    fields: rewriteRelations(collection.fields),
  })
  return `/// <reference path="../pb_data/types.d.ts" />
// GENERATED by web/scripts/gen-created-migrations.mjs — do not edit by hand.
//
// Creates the \`${name}\` collection in its FINAL state (from the canonical
// schema snapshot web/scripts/pb-schema.json) using the collection id that the
// historical updated_* migrations reference. Existing deployments already have
// this collection, so the up() is a no-op for them; fresh instances get the
// full schema and the updated_* migrations below simply no-op on the fields
// they would otherwise add (they are guarded to be idempotent).
migrate((app) => {
  try {
    app.findCollectionByNameOrId("${name}")
    // already exists (pre-existing deployment) — nothing to do
    return
  } catch (e) {
    // not found — create below
  }

  const collection = new Collection(${body})

  return app.save(collection)
}, (app) => {
  try {
    const collection = app.findCollectionByNameOrId("${name}")
    return app.delete(collection)
  } catch (e) {
    // nothing to delete
  }
})
`
}

// users sync migration — users always exists (system auth collection), so patch
// the missing custom fields and finalize the rules instead of creating.
function usersSyncMigration(users) {
  const customFields = rewriteRelations(
    users.fields.filter(
      (f) => !f.system && !["email", "emailVisibility", "verified", "name", "avatar"].includes(f.name) && f.name !== "group_ids"
    )
  )
  // pass the field objects straight into `new Field(...)` (no runtime helper)
  const fieldDefs = customFields
  const rules = {
    listRule: users.listRule,
    viewRule: users.viewRule,
    createRule: users.createRule,
    updateRule: users.updateRule,
    deleteRule: users.deleteRule,
  }
  const rulesJson = json(rules)
  const body = `/// <reference path="../pb_data/types.d.ts" />
// GENERATED by web/scripts/gen-created-migrations.mjs — do not edit by hand.
//
// The \`users\` auth collection is auto-created by PocketBase on fresh boot with
// only the default fields. The custom fields (department_id, role_id, ...) were
// historically added in the admin UI, never via migration, so a fresh instance
// came up without them and every role-based API rule silently failed. This sync
// adds whatever custom fields are missing (idempotent — existing deployments
// already have them) and pins the final rules.
migrate((app) => {
  const collection = app.findCollectionByNameOrId("_pb_users_auth_")

  const names = collection.fields.fieldNames()
  for (const f of ${JSON.stringify(fieldDefs)}) {
    if (!names.includes(f.name)) {
      collection.fields.add(new Field(f))
    }
  }

  unmarshal(${rulesJson}, collection)

  return app.save(collection)
}, (app) => {
  // best-effort revert: remove the custom fields we may have added
  try {
    const collection = app.findCollectionByNameOrId("_pb_users_auth_")
    for (const name of ["department_id", "role_id", "reminder_days", "disabled"]) {
      const field = collection.fields.getByName(name)
      if (field && !field.system) collection.fields.removeById(field.id)
    }
    app.save(collection)
  } catch (e) { /* ignore */ }
})
`
  return body
}

function plansGroupIdMigration() {
  return `/// <reference path="../pb_data/types.d.ts" />
// GENERATED by web/scripts/gen-created-migrations.mjs — do not edit by hand.
//
// Adds \`plans.group_id\` (relation to professional_groups). This must run AFTER
// professional_groups exists (created at 1786900000), because PocketBase
// validates relation targets when the collection is saved. Idempotent.
migrate((app) => {
  const collection = app.findCollectionByNameOrId("plans")
  if (!collection.fields.getByName("group_id")) {
    collection.fields.add(new Field({
      "cascadeDelete": false,
      "collectionId": "pbc_professional_groups",
      "hidden": false,
      "id": "rel_plans_group",
      "maxSelect": 1,
      "minSelect": 0,
      "name": "group_id",
      "presentable": false,
      "required": false,
      "system": false,
      "type": "relation"
    }))
  }
  return app.save(collection)
}, (app) => {
  try {
    const collection = app.findCollectionByNameOrId("plans")
    const field = collection.fields.getByName("group_id")
    if (field && !field.system) collection.fields.removeById(field.id)
    app.save(collection)
  } catch (e) { /* ignore */ }
})
`
}

function usersGroupIdsMigration() {
  return `/// <reference path="../pb_data/types.d.ts" />
// GENERATED by web/scripts/gen-created-migrations.mjs — do not edit by hand.
//
// Adds \`users.group_ids\` (relation to professional_groups). This must run AFTER
// professional_groups exists (created at 1786900000), because PocketBase
// validates relation targets when the collection is saved. Idempotent.
migrate((app) => {
  const collection = app.findCollectionByNameOrId("_pb_users_auth_")
  if (!collection.fields.getByName("group_ids")) {
    collection.fields.add(new Field({
      "cascadeDelete": false,
      "collectionId": "pbc_professional_groups",
      "hidden": false,
      "id": "rel_users_group_ids",
      "maxSelect": 100,
      "minSelect": 0,
      "name": "group_ids",
      "presentable": false,
      "required": false,
      "system": false,
      "type": "relation"
    }))
  }
  return app.save(collection)
}, (app) => {
  try {
    const collection = app.findCollectionByNameOrId("_pb_users_auth_")
    const field = collection.fields.getByName("group_ids")
    if (field && !field.system) collection.fields.removeById(field.id)
    app.save(collection)
  } catch (e) { /* ignore */ }
})
`
}

// ---------------------------------------------------------------- main
const collections = loadSchema()
if (!collections.length) throw new Error("empty schema snapshot: " + SCHEMA)

const users = collections.find((c) => c.name === "users")
if (!users) throw new Error("users collection missing from snapshot")

// remove stale generated files from previous runs (idempotent regeneration)
const CURRENT = new Set([
  ...Object.entries(TS).map(([n, ts]) => `${ts}_created_${n}.js`),
  USERS_GROUP_IDS_FILE,
  PLANS_GROUP_ID_FILE,
])
for (const f of readdirSync(MIG_DIR)) {
  const isGenerated = /^17\d{8}_created_(departments|roles|plans|tasks|comments|proposals|kpi_scores|notifications|system_logs|users)\.js$/.test(f) ||
    /^17870000\d\d_sync_(users_group_ids|plans_group_id)\.js$/.test(f)
  if (isGenerated && !CURRENT.has(f)) {
    rmSync(join(MIG_DIR, f), { force: true })
    console.log(`  removed stale ${f}`)
  }
}

let written = 0
for (const name of ["departments", "roles", "plans", "tasks", "comments", "proposals", "kpi_scores", "notifications", "system_logs"]) {
  const collection = collections.find((c) => c.name === name)
  if (!collection) throw new Error("collection missing from snapshot: " + name)
  // Fields whose relation target does not exist yet at creation time (PB
  // validates relation targets on save) are deferred to later migrations:
  //   - plans.group_id  -> professional_groups (created at 1786900000)
  //   - comments.quote_id -> self-reference (added by 1789000000_add_comment_quote)
  const deferred =
    name === "plans" ? ["group_id"] : name === "comments" ? ["quote_id"] : []
  const body =
    deferred.length
      ? { ...collection, fields: collection.fields.filter((f) => !deferred.includes(f.name)) }
      : collection
  const file = join(MIG_DIR, `${TS[name]}_created_${name}.js`)
  writeFileSync(file, createdMigration(name, body))
  console.log(`  wrote ${file}`)
  written++
}

writeFileSync(join(MIG_DIR, `${TS.users}_created_users.js`), usersSyncMigration(users))
console.log(`  wrote ${join(MIG_DIR, `${TS.users}_created_users.js`)}`)
writeFileSync(join(MIG_DIR, USERS_GROUP_IDS_FILE), usersGroupIdsMigration())
console.log(`  wrote ${join(MIG_DIR, USERS_GROUP_IDS_FILE)}`)
writeFileSync(join(MIG_DIR, PLANS_GROUP_ID_FILE), plansGroupIdMigration())
console.log(`  wrote ${join(MIG_DIR, PLANS_GROUP_ID_FILE)}`)

console.log(`\nGenerated ${written + 3} migration files in ${MIG_DIR}`)
